<?php require_once __DIR__.'/../includes/bootstrap.php';$code=(string)($_GET['code']??'');if(!valid_alias($code))fail(404,'Link not found','This short link is invalid.');$s=db()->prepare('SELECT id,destination_url,is_active,expires_at FROM short_links WHERE code=? LIMIT 1');$s->execute([$code]);$link=$s->fetch();if(!$link)fail(404,'Link not found','This short link does not exist.');if(!(bool)$link['is_active'])fail(410,'Link disabled','The owner has disabled this short link.');if($link['expires_at']&&strtotime($link['expires_at'])<=time())fail(410,'Link expired','This short link has expired.');$ip=$_SERVER['REMOTE_ADDR']??'';$ipHash=$ip!==''?hash('sha256',$ip.config()['session_name']):null;$ua=substr((string)($_SERVER['HTTP_USER_AGENT']??''),0,512);try{$pdo=db();$pdo->beginTransaction();$pdo->prepare('UPDATE short_links SET click_count=click_count+1,last_clicked_at=NOW() WHERE id=?')->execute([$link['id']]);$pdo->prepare('INSERT INTO link_clicks(short_link_id,user_agent,ip_hash) VALUES(?,?,?)')->execute([$link['id'],$ua,$ipHash]);$pdo->commit();}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log('Click tracking failure: '.$e->getMessage());}header('Location: '.$link['destination_url'],true,302);exit;
